                    var onBack = setInterval(() => {
                        var isBack = (window.wv.getMap("onBack") ?? "") === "back";

                        if(!(window.location.pathname !== "/" && window.location.pathname !== "")) window.wv.setMap("onBack", "ended");
                        else if(isBack && history.length > 1) {
                            history.back();
                            window.wv.removeMap("onBack");
                        }
                        else if(history.length > 1) window.wv.removeMap("onBack");
                    }, 10);

                    setHeader();
                    document.addEventListener('click', (event) => clicker(event.target, event));
